def sha(s):return hashlib.sha256(s.encode()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--mode',choices=('validate','apply'),required=True);args=ap.parse_args()
 if not HTML.exists():raise SystemExit('ERROR: cosmos-next.html missing')
 text=HTML.read_text()
 if sha(text)==TARGET_HASH:
  print('Frontend v9.4.2 already installed.')
  result=text
 else:
  if sha(text)!=SOURCE_HASH:raise SystemExit('STOP: frontend differs from the expected combined v9.4.1. No files changed. Obtain current source for a new guarded patch.')
  if text.count(MARKER)!=1:raise SystemExit('STOP: cannot locate unique v9.4.1 interest section')
  result=text.split(MARKER,1)[0]+FRONTEND_SECTION+'\n</body>\n</html>\n'
  if sha(result)!=TARGET_HASH:raise SystemExit('STOP: patched frontend checksum mismatch')
 generator_file=ROOT/'scripts/cosmos_interest_feeds_v941.mjs'
 if not generator_file.exists():raise SystemExit('STOP: existing interest generator missing; rerun combined install first')
 gen_old=generator_file.read_text()
 if args.mode=='validate':print('PASS: frontend output verified, generator target validated; no files written.');return
 if result!=text:HTML.write_text(result)
 if gen_old!=GENERATOR:generator_file.write_text(GENERATOR)
 print('APPLIED: frontend and generator v9.4.2. No workflow files modified.')
if __name__=='__main__':main()
